<?php
declare(strict_types=1);
if(!is_file(__DIR__.'/config.php')){header('Location: install.php');exit;}
require __DIR__.'/participant-auth.php';require __DIR__.'/auth-view.php';$user=lqr_auth_require_user();$message=null;$error=null;
try{if(($_POST['action']??'')==='save_profile'){$name=trim((string)($_POST['display_name']??''));if($name==='')throw new RuntimeException('Enter your name.');lqr_auth_db()->prepare('UPDATE lqr_users SET display_name=?,updated_at=NOW() WHERE public_id=?')->execute([$name,(string)$user['public_id']]);$user=lqr_auth_user_by_id((string)$user['public_id'])??$user;$message='Profile updated.';}elseif(($_POST['action']??'')==='start_link'){$state=lqr_load_state();$appUser=lqr_get_user($state,lqr_config(),(string)$user['public_id']);$response=lqr_action_start_account_link($state,lqr_config(),$appUser);lqr_save_state($state);if(is_array($response['body']??null)&&!empty($response['body']['link_url'])){header('Location: '.(string)$response['body']['link_url']);exit;}throw new RuntimeException('Microgifter account linking could not be started.');}}catch(Throwable $e){$error=$e->getMessage();}
lqr_auth_header('Your profile','Manage your Local Quest participant account and Microgifter connection.');?>
<h2>Your account</h2><p>Manage your identity, email status, and connected reward account.</p><?php lqr_auth_notice($message);lqr_auth_notice($error,true);?>
<div class="profile-grid"><section class="profile-card"><h3>Participant profile</h3><form method="post"><label>Name<input name="display_name" value="<?=lqr_h((string)$user['display_name'])?>" required></label><label>Email<input value="<?=lqr_h((string)$user['email'])?>" disabled></label><button class="button" name="action" value="save_profile">Save profile</button></form></section><section class="profile-card"><h3>Email status</h3><span class="status <?=empty($user['email_verified_at'])?'warn':''?>"><?=empty($user['email_verified_at'])?'Verification required':'Verified'?></span><?php if(empty($user['email_verified_at'])):?><a class="button secondary" href="resend-verification.php">Resend verification</a><?php endif;?><h3 style="margin-top:24px">Microgifter</h3><span class="status <?=empty($user['linked_account_id'])?'warn':''?>"><?=empty($user['linked_account_id'])?'Not connected':'Connected'?></span><?php if(empty($user['linked_account_id'])):?><form method="post"><button class="button" name="action" value="start_link">Connect Microgifter</button></form><?php endif;?></section></div><a class="button secondary" href="account-security.php">Account security</a><a class="button secondary" href="index.php">Open quest board</a><a class="button secondary" href="logout.php">Sign out</a><?php lqr_auth_footer();